import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), k = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // prefix[i]: total cost of the edges between positions 0..i.
        long[] prefix = new long[n];
        for (int i = 1; i < n; i++) prefix[i] = prefix[i - 1] + Math.abs(a[i] - a[i - 1]);
        long answer = prefix[n - 1];
        for (int start = 0; start + k <= n; start++) {
            int end = start + k - 1, lo = Math.max(0, start - 1), hi = Math.min(n - 1, end + 1);
            long cost = prefix[n - 1] - (prefix[hi] - prefix[lo]);
            if (start > 0 && end + 1 < n) cost += Math.abs(a[end + 1] - a[start - 1]);
            answer = Math.min(answer, cost);
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := nextInt(), nextInt()
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	// prefix[i]: total cost of the edges between positions 0..i.
	prefix := make([]int, n)
	for i := 1; i < n; i++ {
		prefix[i] = prefix[i-1] + abs(a[i]-a[i-1])
	}
	answer := prefix[n-1]
	for start := 0; start+k <= n; start++ {
		end := start + k - 1
		lo, hi := max(0, start-1), min(n-1, end+1)
		cost := prefix[n-1] - (prefix[hi] - prefix[lo])
		if start > 0 && end+1 < n {
			cost += abs(a[end+1] - a[start-1])
		}
		answer = min(answer, cost)
	}
	fmt.Println(answer)
}
